<?= $this->extend('layouts/staff') ?><?= $this->section('content') ?><?= view('components/page_header',['title'=>'SMS Notifications','description'=>'Compose and queue personalized reminders. Messages dispatch in the background.']) ?><?php if(session('message')): ?><p class="mb-4 rounded-lg bg-green-50 p-3 text-sm text-green-800"><?= esc(session('message')) ?></p><?php endif ?><?php if(session('error')): ?><p class="mb-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><?= esc(session('error')) ?></p><?php endif ?>
<div class="grid gap-5 xl:grid-cols-3"><section class="card p-5 xl:col-span-2"><h2 class="text-lg font-semibold">Send SMS / Reminder</h2><form class="mt-4 space-y-4" method="post" action="<?= site_url('sms') ?>" data-recipient-count-url="<?= site_url('sms/recipients/count.json') ?>"><?= csrf_field() ?><div class="grid gap-4 sm:grid-cols-2"><div><label class="form-label" for="title">Batch title</label><input class="form-control" id="title" name="title" value="<?= esc(old('title','Health reminder')) ?>"></div><div class="flex items-end text-sm text-gray-500">Choose a saved template below or write a custom message.</div></div>
<div class="grid gap-4 sm:grid-cols-2"><div><label class="form-label" for="recipient_type">Recipients</label><select class="form-control" id="recipient_type" name="recipient_type" x-data x-on:change="$dispatch('recipient-change',$event.target.value)"><option value="all">All primary guardians</option><option value="purok">By purok</option><option value="category">By health category</option><option value="due">Doses due in a date range</option><option value="overdue">Overdue immunizations</option><option value="selected">Hand-picked children</option></select></div><div class="flex items-end"><span class="rounded-full bg-blue-100 px-3 py-2 text-sm font-semibold text-blue-800"><span id="recipient-count">Loading eligible recipients…</span></span></div></div>
<div class="grid gap-3 sm:grid-cols-2" x-data="{kind:'all'}" @recipient-change.window="kind=$event.detail"><div x-show="kind==='purok'"><label class="form-label" for="purok_id">Purok</label><select class="form-control" id="purok_id" name="purok_id"><option value="">All puroks</option><?php foreach($puroks as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?></option><?php endforeach ?></select></div><div x-show="kind==='category'"><label class="form-label" for="category">Health category</label><select class="form-control" id="category" name="category"><?php foreach($categories as $k=>$label): ?><option value="<?= $k ?>"><?= esc($k.' · '.$label) ?></option><?php endforeach ?></select></div><template x-if="kind==='due'"><div class="grid grid-cols-2 gap-3"><div><label class="form-label" for="due_from">Due from</label><input class="form-control" id="due_from" name="due_from" type="date"></div><div><label class="form-label" for="due_to">Due to</label><input class="form-control" id="due_to" name="due_to" type="date"></div></div></template><div x-show="kind==='selected'" class="sm:col-span-2"><label class="form-label" for="child_ids">Child IDs (comma-separated)</label><input class="form-control" id="child_ids" name="child_ids_text" placeholder="Enter child record IDs"></div></div>
<div><label class="form-label" for="template_id">Template</label><input type="hidden" id="message_type" name="message_type" value="general"><select class="form-control" id="template_id" name="template_id"><option value="">Custom message</option><?php foreach($templates as $t): ?><option value="<?= $t['id'] ?>" data-body="<?= esc($t['body']) ?>" data-type="<?= esc($t['type']) ?>"><?= esc($t['name']) ?></option><?php endforeach ?></select></div><div><label class="form-label" for="body">Message</label><textarea class="form-control min-h-32" id="body" name="body" maxlength="1000" required><?= esc(old('body','Hello {guardian_name}, please visit {center_name}.')) ?></textarea><div class="mt-2 flex flex-wrap items-center justify-between gap-2 text-xs text-gray-500"><div class="flex flex-wrap gap-1"><?php foreach(['guardian_name','child_name','vaccine','date','time','center_name'] as $placeholder): ?><button class="rounded bg-gray-100 px-2 py-1" type="button" data-placeholder="{<?= $placeholder ?>}"><?= '{'.$placeholder.'}' ?></button><?php endforeach ?></div><span id="segment-count">0 characters · 1 SMS segment</span></div></div>
<div class="grid gap-4 sm:grid-cols-3"><div><label class="form-label" for="send_mode">Send timing</label><select class="form-control" id="send_mode" name="send_mode"><option value="now">Queue now</option><option value="schedule">Schedule</option></select></div><div><label class="form-label" for="scheduled_date">Schedule date</label><input class="form-control" id="scheduled_date" name="scheduled_date" type="date" min="<?= date('Y-m-d') ?>"></div><div><label class="form-label" for="scheduled_time">Schedule time</label><input class="form-control" id="scheduled_time" name="scheduled_time" type="time" value="09:00"></div></div><div class="rounded-lg bg-gray-50 p-3 text-sm"><strong>Preview:</strong> <span id="message-preview"><?= esc(strtr(old('body','Hello {guardian_name}, please visit {center_name}.'),['{guardian_name}'=>'Parent','{child_name}'=>'Child','{vaccine}'=>'Vaccine','{date}'=>date('M j'),'{time}'=>'9:00 AM','{center_name}'=>setting('ChildCare.center_name')??'Health Center'])) ?></span><p class="mt-1 text-gray-500">Each guardian receives a personalized message. Quiet hours are 9:00 PM–7:00 AM.</p></div><button class="btn-primary">Queue SMS</button></form></section>
<aside class="space-y-5"><section class="card p-5"><h2 class="text-lg font-semibold">SMS statistics · this month</h2><?php $stats=db_connect()->table('sms_messages')->select('status,COUNT(*) AS total')->where('created_at >=',date('Y-m-01 00:00:00'))->groupBy('status')->get()->getResultArray(); foreach(['sent'=>'Total sent','delivered'=>'Delivered','queued'=>'Pending','failed'=>'Failed'] as $status=>$label): $value=0;foreach($stats as $s)if($s['status']===$status)$value=(int)$s['total']; ?><div class="flex justify-between border-b border-gray-100 py-2 text-sm"><span><?= esc($label) ?></span><strong><?= $value ?></strong></div><?php endforeach ?><a class="mt-3 inline-block text-sm text-accent" href="<?= site_url('sms/logs') ?>">View message logs →</a></section><section class="card p-5"><h2 class="text-lg font-semibold">Recent batches</h2><div class="mt-3 space-y-3"><?php foreach($batches as $b): ?><div class="border-b border-gray-100 pb-2 text-sm"><strong><?= esc($b['title']) ?></strong><span class="block text-xs text-gray-500"><?= (int)$b['recipient_count'] ?> recipients · <?= esc(format_date($b['created_at'])) ?></span></div><?php endforeach ?><?php if(!$batches): ?><p class="text-sm text-gray-500">No SMS batches yet.</p><?php endif ?></div><div class="mt-4 flex flex-wrap gap-2"><a class="btn-muted" href="<?= site_url('sms/templates') ?>">Manage templates</a><a class="btn-muted" href="<?= site_url('sms/logs') ?>">SMS Logs</a></div></section></aside></div>
